import { isArray, isEmpty, isNil } from 'lodash';
import { ERRORS } from './';

function requiredValidator({ errors, value }) {
  if (
    isNil(value) ||
    (isArray(value) && isEmpty(value)) ||
    !/\S/.test(value) ||
    value === false
  ) {
    errors.push(ERRORS.isRequired);
  }

  return errors;
}

export default requiredValidator;
